<?php $nq = count($pendingThreads) + count($pendingPosts); ?>
<div class="tabs"><a class="<?= $tab === 'queue' ? 'on' : '' ?>" href="/admin/forum">Approval queue<?= $nq ? ' (' . $nq . ')' : '' ?></a><a class="<?= $tab === 'reports' ? 'on' : '' ?>" href="/admin/forum?tab=reports">Reports<?= $reports ? ' (' . count($reports) . ')' : '' ?></a><a class="<?= $tab === 'categories' ? 'on' : '' ?>" href="/admin/forum?tab=categories">Categories</a><a class="<?= $tab === 'recent' ? 'on' : '' ?>" href="/admin/forum?tab=recent">Recent</a></div>
<?php if ($tab === 'queue'): ?>
<p class="muted small">New members’ first posts are held here. Approving a post marks the member as trusted so their later posts publish instantly. (Turn this off under Settings.)</p>
<?php foreach ($pendingThreads as $t): ?><div class="panel"><div class="panel-b"><strong><?= e($t['title']) ?></strong> <span class="muted small">· new discussion in <?= e($t['cat']) ?> by <?= e($t['author']) ?> · <?= e(ago($t['created_at'])) ?></span><div class="md small" style="margin:10px 0"><?= md($t['body']) ?></div>
  <form method="post" action="/admin/forum/moderate" class="tbl-actions"><?= csrf_field() ?><input type="hidden" name="kind" value="thread"><input type="hidden" name="id" value="<?= (int) $t['id'] ?>"><button class="btn btn-primary btn-xs" name="action" value="approve">Approve</button><button class="btn btn-ghost btn-xs" name="action" value="reject" data-confirm="Reject and remove?">Reject</button></form></div></div><?php endforeach; ?>
<?php foreach ($pendingPosts as $p): ?><div class="panel"><div class="panel-b"><span class="muted small">Reply by <strong><?= e($p['author']) ?></strong> in <a href="/forum/t/<?= (int) $p['tid'] ?>"><?= e($p['thread_title']) ?></a></span><div class="md small" style="margin:10px 0"><?= md($p['body']) ?></div>
  <form method="post" action="/admin/forum/moderate" class="tbl-actions"><?= csrf_field() ?><input type="hidden" name="kind" value="post"><input type="hidden" name="id" value="<?= (int) $p['id'] ?>"><button class="btn btn-primary btn-xs" name="action" value="approve">Approve</button><button class="btn btn-ghost btn-xs" name="action" value="reject">Reject</button></form></div></div><?php endforeach; ?>
<?php if (!$nq): ?><?= empty_state('check', 'Nothing waiting for approval', 'New posts from first-time members appear here.') ?><?php endif; ?>
<?php elseif ($tab === 'reports'): ?>
<?php foreach ($reports as $r): $c = $r['content']; ?><div class="panel"><div class="panel-b"><span class="muted small">Reported by <?= e($r['reporter'] ?: 'a member') ?> · <?= e(ago($r['created_at'])) ?> · reason: <strong><?= e($r['reason']) ?></strong></span>
  <?php if ($c): ?><div class="md small" style="margin:10px 0;background:#fafcfb;padding:10px;border-radius:10px"><strong><?= e($c['author']) ?>:</strong> <?= md($c['body']) ?><a class="small" href="/forum/t/<?= (int) $c['thread_id'] ?>">View in context</a></div><?php else: ?><p class="muted small">The content no longer exists.</p><?php endif; ?>
  <form method="post" action="/admin/forum/moderate" class="tbl-actions"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $r['id'] ?>"><button class="btn btn-ghost btn-xs" name="action" value="dismiss">Dismiss</button><button class="btn btn-danger btn-xs" name="action" value="remove" data-confirm="Remove the reported content?">Remove content</button><?php if ($c && is_super()): ?><input type="hidden" name="user_id" value="<?= (int) $c['user_id'] ?>"><button class="btn btn-ghost btn-xs" name="action" value="suspend_author" data-confirm="Suspend this member’s account?">Suspend author</button><?php endif; ?></form></div></div><?php endforeach; ?>
<?php if (!$reports): ?><?= empty_state('shield', 'No open reports', 'Reported content will appear here.') ?><?php endif; ?>
<?php elseif ($tab === 'categories'): ?>
<div class="table-wrap"><table class="t"><thead><tr><th>Category</th><th>Discussions</th><th>Settings</th></tr></thead><tbody><?php foreach ($cats as $c): ?><tr><td colspan="3"><form method="post" action="/admin/forum/category" class="form" style="grid-template-columns:1.2fr 2fr 130px 90px auto auto;align-items:center;gap:8px"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $c['id'] ?>"><input name="name" value="<?= e($c['name']) ?>"><input name="description" value="<?= e($c['description']) ?>"><select name="icon"><?php foreach (['chat', 'megaphone', 'briefcase', 'building', 'monitor', 'book', 'alert', 'users', 'zap', 'globe'] as $i) { echo '<option' . ($c['icon'] === $i ? ' selected' : '') . '>' . $i . '</option>'; } ?></select><input type="number" name="pos" value="<?= (int) $c['pos'] ?>" title="Order"><label class="ck xs"><input type="checkbox" name="staff_only" value="1" <?= $c['staff_only'] ? 'checked' : '' ?>> Staff only</label><span class="tbl-actions"><button class="rowbtn" name="action" value="save">Save</button><button class="rowbtn danger" name="action" value="delete" data-confirm="Delete this category?">×</button></span></form></td></tr><?php endforeach; ?></tbody></table></div>
<form class="panel mt2" method="post" action="/admin/forum/category" style="max-width:700px"><?= csrf_field() ?><input type="hidden" name="action" value="save"><div class="panel-h">Add a category</div><div class="panel-b form"><div class="row2"><?= a_in('Name', 'name', '', ['required' => true]) ?><?= a_in('Description', 'description', '') ?></div><button class="btn btn-ghost btn-sm">Add category</button></div></form>
<?php else: ?>
<div class="table-wrap"><table class="t"><thead><tr><th>Discussion</th><th>Author</th><th>Status</th><th class="num">Replies</th></tr></thead><tbody><?php foreach ($recent as $t): ?><tr><td><a href="/forum/t/<?= (int) $t['id'] ?>-<?= e($t['slug']) ?>"><?= e($t['title']) ?></a></td><td><?= e($t['author']) ?></td><td><?= badge($t['status'], $t['status'] === 'published' ? 'green' : 'amber') ?></td><td class="num"><?= (int) $t['reply_count'] ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>
